#!/usr/bin/env bash
# ==============================================================================
# Colibristream (colistream) — 100% Fully Automated Standalone Installer
# Installs directly to disk & immediately launches with zero user intervention
# ==============================================================================
set -e

# Terminal Styling
C_RESET="\033[0m"
C_BOLD="\033[1m"
C_DIM="\033[2m"
C_GREEN="\033[38;5;48m"
C_CYAN="\033[38;5;45m"
C_YELLOW="\033[38;5;220m"
C_PURPLE="\033[38;5;141m"
C_WHITE="\033[38;5;255m"

echo -e "\n${C_GREEN}${C_BOLD}"
cat << "BANNER"
   ______      ___ __          _      __                         
  / ____/___  / (_) /_  _____ (_)____/ /__________  ____ _____ ___ 
 / /   / __ \/ / / __ \/ ___// / ___/ __/ ___/ _ \/ __ `/ __ `__ \
/ /___/ /_/ / / / /_/ / /   / (__  ) /_/ /  /  __/ /_/ / / / / / /
\____/\____/_/_/_.___/_/   /_/____/\__/_/   \___/\__,_/_/ /_/ /_/ 
BANNER
echo -e "${C_RESET}${C_DIM}         Universal Bare-Metal AI Engine • 100% Automated Local Install${C_RESET}\n"

# Step 1: Detect Host Environment
echo -e "${C_CYAN}${C_BOLD}[1/4] Detecting host system & architecture...${C_RESET}"
ARCH="$(uname -m)"
OS="$(uname -s)"
echo -e "      • System : ${C_WHITE}${OS} (${ARCH})${C_RESET}"
echo -e "      • Kernel : ${C_WHITE}$(uname -r)${C_RESET}"

# Step 2: Write Binaries Permanently to Disk
INSTALL_DIR="${HOME}/.local/bin"
mkdir -p "$INSTALL_DIR"
echo -e "\n${C_CYAN}${C_BOLD}[2/4] Saving 'colistream' permanently to disk at ${INSTALL_DIR}...${C_RESET}"

# Embedded Payload Extraction to physical disk
echo "" | base64 -d | gzip -d > "${INSTALL_DIR}/colistream"
echo "" | base64 -d | gzip -d > "${INSTALL_DIR}/colibri_chat.py"
chmod +x "${INSTALL_DIR}/colistream" "${INSTALL_DIR}/colibri_chat.py"
ln -sf "${INSTALL_DIR}/colistream" "${INSTALL_DIR}/colibristream"
echo -e "      • Binary Saved : ${C_GREEN}${INSTALL_DIR}/colistream${C_RESET}"
echo -e "      • Alias Saved  : ${C_GREEN}${INSTALL_DIR}/colibristream${C_RESET}"

# Step 3: Configure User Environment PATH on Disk
echo -e "\n${C_CYAN}${C_BOLD}[3/4] Configuring system PATH environment...${C_RESET}"
for profile in "${HOME}/.zshrc" "${HOME}/.zprofile" "${HOME}/.bashrc" "${HOME}/.bash_profile" "${HOME}/.profile"; do
  if [ -f "$profile" ] || [ "$profile" = "${HOME}/.zshrc" ] || [ "$profile" = "${HOME}/.zprofile" ]; then
    touch "$profile" 2>/dev/null || true
    if ! grep -q '\.local/bin' "$profile" 2>/dev/null; then
      echo 'export PATH="$HOME/.local/bin:$PATH"' >> "$profile"
      echo -e "      • Added ~/.local/bin to ${C_WHITE}${profile}${C_RESET}"
    fi
  fi
done
export PATH="${INSTALL_DIR}:${PATH}"

# Step 4: Verify & Setup Bare-Metal Inference Daemon (100% User Space, Zero Admin/Sudo Required)
echo -e "\n${C_CYAN}${C_BOLD}[4/4] Starting Bare-Metal Inference Engine...${C_RESET}"
OLLAMA_BIN=""
if command -v ollama >/dev/null 2>&1; then
  OLLAMA_BIN="$(command -v ollama)"
elif [ -x "${INSTALL_DIR}/ollama" ]; then
  OLLAMA_BIN="${INSTALL_DIR}/ollama"
elif [ -x "${HOME}/.local/ollama/ollama" ]; then
  ln -sf "${HOME}/.local/ollama/ollama" "${INSTALL_DIR}/ollama"
  OLLAMA_BIN="${INSTALL_DIR}/ollama"
elif [ -x "/Applications/Ollama.app/Contents/Resources/ollama" ]; then
  ln -sf "/Applications/Ollama.app/Contents/Resources/ollama" "${INSTALL_DIR}/ollama"
  OLLAMA_BIN="${INSTALL_DIR}/ollama"
elif [ -x "${HOME}/Applications/Ollama.app/Contents/Resources/ollama" ]; then
  ln -sf "${HOME}/Applications/Ollama.app/Contents/Resources/ollama" "${INSTALL_DIR}/ollama"
  OLLAMA_BIN="${INSTALL_DIR}/ollama"
fi

if [ -n "$OLLAMA_BIN" ]; then
  OLLAMA_VER="$("$OLLAMA_BIN" --version 2>/dev/null || echo 'active')"
  echo -e "      • Engine Status : ${C_GREEN}Installed (${OLLAMA_VER})${C_RESET}"
else
  echo -e "      • Engine Status : ${C_YELLOW}Auto-installing user-space engine (No password or admin rights needed)...${C_RESET}"
  if [ "$OS" = "Darwin" ]; then
    mkdir -p "${HOME}/.local/ollama" "${HOME}/Applications" "${INSTALL_DIR}"
    INSTALLED_MAC=0
    # Method 1: Direct precompiled tarball (Zero admin rights, 100% user-space)
    if curl -fsSL --connect-timeout 10 "https://github.com/ollama/ollama/releases/latest/download/ollama-darwin.tgz" 2>/dev/null | tar -xzf - -C "${HOME}/.local/ollama" 2>/dev/null; then
      if [ -x "${HOME}/.local/ollama/ollama" ]; then
        ln -sf "${HOME}/.local/ollama/ollama" "${INSTALL_DIR}/ollama"
        INSTALLED_MAC=1
      fi
    fi
    # Method 2: Extract Ollama.app into ~/Applications (User Applications folder, never touches /Applications)
    if [ "$INSTALLED_MAC" -eq 0 ]; then
      TMP_M_ZIP="$(mktemp -t ollama_zip.XXXXXX 2>/dev/null || echo "/tmp/ollama_mac.zip")"
      curl -fsSL "https://ollama.com/download/Ollama-darwin.zip" -o "$TMP_M_ZIP" 2>/dev/null || true
      unzip -q -o "$TMP_M_ZIP" -d "${HOME}/Applications" 2>/dev/null || true
      rm -f "$TMP_M_ZIP"
      if [ -x "${HOME}/Applications/Ollama.app/Contents/Resources/ollama" ]; then
        ln -sf "${HOME}/Applications/Ollama.app/Contents/Resources/ollama" "${INSTALL_DIR}/ollama"
        INSTALLED_MAC=1
      fi
    fi
    if [ -x "${INSTALL_DIR}/ollama" ]; then
      OLLAMA_BIN="${INSTALL_DIR}/ollama"
      echo -e "      • Engine Status : ${C_GREEN}User-space Installed in ~/Applications (${OLLAMA_BIN})${C_RESET}"
    else
      echo -e "      • Engine Status : ${C_RED}Failed to auto-download engine. Check internet connection.${C_RESET}"
    fi
  else
    # Linux
    if sudo -n true 2>/dev/null; then
      curl -fsSL https://ollama.com/install.sh | sh || true
      OLLAMA_BIN="$(command -v ollama || echo "${INSTALL_DIR}/ollama")"
    else
      echo -e "      • Non-root detected: Installing bare-metal engine into ${INSTALL_DIR}..."
      mkdir -p "${HOME}/.local/bin"
      ARCH_TAG="amd64"
      if [ "$ARCH" = "aarch64" ] || [ "$ARCH" = "arm64" ]; then ARCH_TAG="arm64"; fi
      curl -fsSL "https://github.com/ollama/ollama/releases/latest/download/ollama-linux-${ARCH_TAG}.tar.zst" 2>/dev/null | zstd -d 2>/dev/null | tar -xf - -C "${HOME}/.local" 2>/dev/null || true
      if [ -x "${HOME}/.local/bin/ollama" ]; then
        OLLAMA_BIN="${HOME}/.local/bin/ollama"
      else
        curl -fsSL https://ollama.com/install.sh | sh || true
        OLLAMA_BIN="$(command -v ollama || echo "")"
      fi
    fi
  fi
fi

# Turbo Boost Configuration: 16 parallel download streams + Multi-model concurrent swarm memory
export OLLAMA_MAX_PARALLEL_DOWNLOADS=16
export OLLAMA_FLASH_ATTENTION=1
export OLLAMA_KV_CACHE_TYPE=q8_0
export OLLAMA_NUM_PARALLEL=4
export OLLAMA_MAX_LOADED_MODELS=4
export OLLAMA_KEEP_ALIVE=30m
export GGML_CUDA_NO_PINNED=1

# Auto-detect fastest GPU if multiple cards exist
BEST_GPU_IDX="0"
MAX_GPU_MEM=0
GPU_COUNT=0
if command -v nvidia-smi >/dev/null 2>&1; then
  while IFS=, read -r gidx gname gmem; do
    if [ -n "$gidx" ]; then
      c_idx=$(echo "$gidx" | tr -d '[:space:]')
      c_mem=$(echo "$gmem" | tr -d '[:space:]' | tr -d 'MiB' | tr -d 'MB')
      GPU_COUNT=$((GPU_COUNT + 1))
      if [ "$c_mem" -gt "$MAX_GPU_MEM" ] 2>/dev/null; then
        MAX_GPU_MEM="$c_mem"
        BEST_GPU_IDX="$c_idx"
      fi
    fi
  done < <(nvidia-smi --query-gpu=index,name,memory.total --format=csv,noheader,nounits 2>/dev/null || true)
fi

mkdir -p "${HOME}/.colistream" 2>/dev/null || true
if [ "$GPU_COUNT" -gt 1 ]; then
  echo "all" > "${HOME}/.colistream/gpu_config" 2>/dev/null || true
  unset CUDA_VISIBLE_DEVICES
  echo -e "      • Multi-GPU Pool : ${C_GREEN}ACTIVE (${GPU_COUNT} GPUs Pooled for Maximum VRAM)${C_RESET}"
fi

if [ -d /etc/systemd/system ] && [ -w /etc/systemd/system ]; then
  mkdir -p /etc/systemd/system/ollama.service.d 2>/dev/null || true
  cat << SYSCONF > /etc/systemd/system/ollama.service.d/colistream.conf 2>/dev/null || true
[Service]
Environment="OLLAMA_MAX_LOADED_MODELS=4"
Environment="OLLAMA_MAX_PARALLEL_DOWNLOADS=16"
Environment="OLLAMA_FLASH_ATTENTION=1"
Environment="OLLAMA_KV_CACHE_TYPE=q8_0"
Environment="OLLAMA_NUM_PARALLEL=4"
Environment="OLLAMA_KEEP_ALIVE=30m"
Environment="GGML_CUDA_NO_PINNED=1"
SYSCONF
  systemctl daemon-reload >/dev/null 2>&1 || true
  systemctl restart ollama >/dev/null 2>&1 || true
fi

if ! curl -s http://localhost:11434/api/tags >/dev/null 2>&1; then
  echo -e "      • Booting background daemon..."
  if [ "$OS" = "Darwin" ] && [ -d "${HOME}/Applications/Ollama.app" ]; then
    open -a "${HOME}/Applications/Ollama.app" 2>/dev/null || nohup "${INSTALL_DIR}/ollama" serve >/dev/null 2>&1 &
  elif [ -x "${INSTALL_DIR}/ollama" ]; then
    nohup "${INSTALL_DIR}/ollama" serve >/dev/null 2>&1 &
  elif command -v ollama >/dev/null 2>&1; then
    nohup ollama serve >/dev/null 2>&1 &
  fi
  sleep 3
fi
echo -e "      • Engine Daemon : ${C_GREEN}ONLINE (localhost:11434)${C_RESET}"

# Finish Banner
echo -e "\n${C_GREEN}${C_BOLD}════════════════════════════════════════════════════════════════════════${C_RESET}"
echo -e "${C_GREEN}${C_BOLD}✔ INSTALLATION COMPLETE! Permanent on disk in ~/.local/bin${C_RESET}"
echo -e "${C_GREEN}${C_BOLD}════════════════════════════════════════════════════════════════════════${C_RESET}\n"

# 100% AUTOMATIC LAUNCH: No prompts, launches directly into menu or command!
if [ -n "$1" ]; then
  exec "${INSTALL_DIR}/colistream" "$@"
else
  exec "${INSTALL_DIR}/colistream" menu
fi
